rce = arguments[i];\n      for (var key in source) {\n        target[key] = source[key];\n      }\n    }\n    return target\n  }\n  /* eslint-enable no-var */\n\n  /* eslint-disable no-var */\n  var defaultConverter = {\n    read: function (value) {\n      if (value[0] === '\"') {\n        value = value.slice(1, -1);\n      }\n      return value.replace(/(%[\\dA-F]{2})+/gi, decodeURIComponent)\n    },\n    write: function (value) {\n      return encodeURIComponent(value).replace(\n        /%(2[346BF]|3[AC-F]|40|5[BDE]|60|7[BCD])/g,\n        decodeURIComponent\n      )\n    }\n  };\n  /* eslint-enable no-var */\n\n  /* eslint-disable no-var */\n\n  function init (converter, defaultAttributes) {\n    function set (name, value, attributes) {\n      if (typeof document === 'undefined') {\n        return\n      }\n\n      attributes = assign({}, defaultAttributes, attributes);\n\n      if (typeof attributes.expires === 'number') {\n        attributes.expires = new Date(Date.now() + attributes.expires * 864e5);\n      }\n      if (attributes.expires) {\n        attributes.expires = attributes.expires.toUTCString();\n      }\n\n      name = encodeURIComponent(name)\n        .replace(/%(2[346B]|5E|60|7C)/g, decodeURIComponent)\n        .replace(/[()]/g, escape);\n\n      var stringifiedAttributes = '';\n      for (var attributeName in attributes) {\n        if (!attributes[attributeName]) {\n          continue\n        }\n\n        stringifiedAttributes += '; ' + attributeName;\n\n        if (attributes[attributeName] === true) {\n          continue\n        }\n\n        // Considers RFC 6265 section 5.2:\n        // ...\n        // 3.  If the remaining unparsed-attributes contains a %x3B (\";\")\n        //     character:\n        // Consume the characters of the unparsed-attributes up to,\n        // not including, the first %x3B (\";\") character.\n        // ...\n        stringifiedAttributes += '=' + attributes[attributeName].split(';')[0];\n      }\n\n      return (document.cookie =\n        name + '=' + converter.write(value, name) + stringifiedAttributes)\n    }\n\n    function get (name) {\n      if (typeof document === 'undefined' || (arguments.length && !name)) {\n        return\n      }\n\n      // To prevent the for loop in the first place assign an empty array\n      // in case there are no cookies at all.\n      var cookies = document.cookie ? document.cookie.split('; ') : [];\n      var jar = {};\n      for (var i = 0; i < cookies.length; i++) {\n        var parts = cookies[i].split('=');\n        var value = parts.slice(1).join('=');\n\n        try {\n          var found = decodeURIComponent(parts[0]);\n          jar[found] = converter.read(value, found);\n\n          if (name === found) {\n            break\n          }\n        } catch (e) {}\n      }\n\n      return name ? jar[name] : jar\n    }\n\n    return Object.create(\n      {\n        set,\n        get,\n        remove: function (name, attributes) {\n          set(\n            name,\n            '',\n            assign({}, attributes, {\n              expires: -1\n            })\n          );\n        },\n        withAttributes: function (attributes) {\n          return init(this.converter, assign({}, this.attributes, attributes))\n        },\n        withConverter: function (converter) {\n          return init(assign({}, this.converter, converter), this.attributes)\n        }\n      },\n      {\n        attributes: { value: Object.freeze(defaultAttributes) },\n        converter: { value: Object.freeze(converter) }\n      }\n    )\n  }\n\n  var api = init(defaultConverter, { path: '/' });\n  /* eslint-enable no-var */\n\n  return api;\n\n}));\n","import { setCompactStatus, unSetCompactStatus } from './sidebar';\nimport { isCompactExplicit } from '../adminPreferences';\n\n// System to detect when the window's size reaches a given breakpoint\n// Right now it is only used to compact the lefbar when resizing under 768px\n// In the future maybe this is useful to do other things on resizing.\n(function () {\n    const breakPoint = 768;\n    let lastDirection = '';\n    let lastDirectionManaged = '';\n    let breakpointChangeManaged = false;\n    let lastWidth = document.body.clientWidth;\n\n    window.addEventListener('resize', () => {\n\n        const width = document.body.clientWidth;\n        const direction = width < lastWidth ? 'reducing' : 'increasing';\n\n        if (direction !== lastDirection) {\n            breakpointChangeManaged = false; // need to listen for breakpoint            \n        }\n\n        if (breakpointChangeManaged == false && direction != lastDirectionManaged) {\n            if (direction == 'reducing' && width < breakPoint) {\n                // breakpoint reached while going down\n                setCompactStatus(isCompactExplicit);\n                lastDirectionManaged = direction;\n                breakpointChangeManaged = true;\n            }\n\n            if (direction == 'increasing' && width > breakPoint) {\n                // breakpoint reached while going up\n                if (isCompactExplicit == false) {\n                    unSetCompactStatus();\n                }\n                lastDirectionManaged = direction;\n                breakpointChangeManaged = true;\n            }\n        }\n\n        lastDirection = direction;\n        lastWidth = width;\n    });\n})();","import { getAdminPreferences, setAdminPreferences } from '../adminPreferences';\n\n// Manages the action bar at runtime.\n//\n// This file must remain in the foot bundle (TheAdmin.ts) and must NOT be imported\n// from the head bundle (TheAdmin-main.ts). It contains a DOM-dependent IIFE that\n// queries live elements, so it requires the DOM to already exist. Its observers\n// also serve the opposite purpose from the head-bundle observer: they *save* state\n// changes made by the user, whereas the head-bundle observer *restores* saved state\n// before the first paint.\n(function () {\n\n    const actionBar = document.querySelector<HTMLElement>('.action-bar-bottom');\n    if (!actionBar) return;\n\n    new ResizeObserver(() => {\n        document.documentElement.style.setProperty('--oc-action-bar-bottom-height', actionBar.offsetHeight + 'px');\n    }).observe(actionBar);\n\n    // Persist the collapse state to admin preferences so it survives page navigation.\n    // Bootstrap updates aria-expanded on the toggle synchronously on every show/hide,\n    // so a MutationObserver on that single attribute is the most reliable hook.\n    const toggle = actionBar.querySelector<HTMLButtonElement>('.action-bar-toggle');\n    if (toggle) {\n        // If actionBarCollapseLoader (head bundle) pre-expanded the toggle, Bootstrap's\n        // Collapse plugin has no matching .show class on the targets yet — so its first\n        // click would call show() instead of hide(), wasting one click. Sync the state now.\n        if (toggle.getAttribute('aria-expanded') === 'true') {\n            actionBar.querySelectorAll<HTMLElement>('.action-bar-collapsible').forEach(el => {\n                el.classList.add('show');\n            });\n        }\n\n        new MutationObserver(() => {\n            const prefs = getAdminPreferences();\n            prefs.actionBarCollapsed = toggle.getAttribute('aria-expanded') !== 'true';\n            setAdminPreferences(prefs);\n        }).observe(toggle, { attributes: true, attributeFilter: ['aria-expanded'] });\n    }\n})();\n\n","import { getAdminPreferences, setAdminPreferences, AdminPreferences } from '../adminPreferences';\n\n// Persists the last-used action of a [data-action-group] button group so that\n// the main button switches to the alternative action on the next page load.\n// The data attributes are expected to be set by module views; if they are absent\n// the group is silently skipped.\n// State is stored inside the tenant-scoped admin preferences managed by adminPreferences.ts.\n\n// applyActionGroupStateToNode is called from TheAdmin-main.ts via the shared\n// MutationObserver to apply the stored state before the first paint, avoiding a\n// visible flicker when the alt action was last used.\n\nconst applyActionGroupState = (group: HTMLElement, actionGroups: Record<string, string>) => {\n    const storageKey = group.dataset.actionGroup!;\n    const storedAction = actionGroups[storageKey];\n    if (storedAction !== group.dataset.actionAlt) return;\n\n    const mainBtn = group.querySelector<HTMLButtonElement>('button[type=\"submit\"]');\n    const dropdownItem = group.querySelector<HTMLButtonElement>('.dropdown-item');\n    if (!mainBtn || !dropdownItem) return;\n\n    mainBtn.value = group.dataset.actionAlt!;\n    mainBtn.textContent = group.dataset.labelAlt!;\n    dropdownItem.value = group.dataset.actionDefault!;\n    dropdownItem.textContent = group.dataset.labelDefault!;\n};\n\nexport const applyActionGroupStateToNode = (node: Node, adminPreferences: AdminPreferences) => {\n    if (!adminPreferences?.actionGroups) return;\n    if (!(node instanceof HTMLElement)) return;\n    const groups = adminPreferences.actionGroups as Record<string, string>;\n    if (node.matches('.btn-group[data-action-group]')) applyActionGroupState(node, groups);\n    node.querySelectorAll<HTMLElement>('.btn-group[data-action-group]').forEach(group => applyActionGroupState(group, groups));\n};\n\n// Wire up click handlers at DOMContentLoaded. The guard prevents double-initialisation\n// when both the head bundle (TheAdmin-main) and the foot bundle (TheAdmin) include this module.\ndocument.addEventListener('DOMContentLoaded', () => {\n    document.querySelectorAll<HTMLElement>('.btn-group[data-action-group]').forEach(initActionGroup);\n});\n\nfunction initActionGroup(group: HTMLElement) {\n    if (group.dataset.actionGroupInit !== undefined) return;\n    group.dataset.actionGroupInit = '';\n\n    const storageKey = group.dataset.actionGroup!;\n    const dropdownItem = group.querySelector<HTMLButtonElement>('.dropdown-item');\n    if (!dropdownItem) return;\n\n    // On dropdown item click: store the new default, then let the form submit naturally\n    dropdownItem.addEventListener('click', () => {\n        const prefs = getAdminPreferences() as AdminPreferences;\n        prefs.actionGroups = prefs.actionGroups ?? {};\n        prefs.actionGroups[storageKey] = dropdownItem.value;\n        setAdminPreferences(prefs);\n    });\n}"],"names":["parcelHelpers","export","exports","confirmDialog","require","callback","options","defaultOptions","$","data","title","message","okText","cancelText","okClass","cancelClass","extend","appendTo","modalElement","document","getElementById","confirmModal","bootstrap","Modal","backdrop","keyboard","show","addEventListener","remove","dispose","click","hide","body","classList","on","_this","this","filter","length","console","warn","resp","url","attr","undefined","form","parents","append","submit","window","location","href","magicToken","first","hrefParts","split","clone","queryParts","i","queryPartKVP","decodeURIComponent","css","position","left","unsafeUrlPrompt","slice","call","querySelectorAll","map","tooltipTriggerEl","Tooltip","e","submittingClass","hasClass","preventDefault","addClass","setTimeout","removeClass","setCompactStatus","unSetCompactStatus","_adminPreferences","width","each","prev","prop","text","prefs","getAdminPreferences","selectedNavHash","String","setAdminPreferences","event","$trigger","target","has","Array","explicit","labels","menuAdmin","querySelector","savedScroll","scrollTop","leftNav","setCompactExplicit","persistAdminPreferences","resizeObserver","ResizeObserver","entries","isCompactExplicit","scrollHeight","clientHeight","add","observe","_globals","_jsCookie","value","getAdminPreferenceKey","getTenantName","storedValue","localStorage","getItem","JSON","parse","ex","error","adminPreferences","key","setItem","stringify","_jsCookieDefault","default","set","expires","leftSidebarCompact","contains","getAntiForgeryToken","getTenantPathBase","get