AKhL,KAAKiL,UAAWH,EAAO,CAAC,EAAG9K,KAAKmL,WAAYA,GAC1D,EACAkB,cAAe,SAAUpB,GACvB,OAAOD,EAAKF,EAAO,CAAC,EAAG9K,KAAKiL,UAAWA,GAAYjL,KAAKmL,WAC1D,GAEF,CACEA,WAAY,CAAE9D,MAAO6C,OAAOoC,OAAOpB,IACnCD,UAAW,CAAE5D,MAAO6C,OAAOoC,OAAOrB,KAGxC,CAKA,OAHUD,EApHa,CACrBkB,KAAM,SAAU7E,GAId,MAHiB,MAAbA,EAAM,KACRA,EAAQA,EAAMxF,MAAM,GAAG,IAElBwF,EAAMwC,QAAQ,mBAAoBrI,mBAC3C,EACAoK,MAAO,SAAUvE,GACf,OAAOkE,mBAAmBlE,GAAOwC,QAC/B,2CACArI,mBAEJ,GAwG+B,CAAE+K,KAAM,KAK3C,CA/IkFC,E,yJCErEvF,GALb,IAAApE,EAAA9E,EAAA,gBAKO,MAAMkJ,EAA0B,KACnCzE,WAAW,WACP,IAAIoF,EAAmB,CAAC,EACxBA,EAAiB6E,qBAAqB3N,SAASc,KAAKC,UAAU6M,SAAS,wBACvE9E,EAAiBxB,kBAAoBvD,EAAAuD,mBACrC,EAAAvD,EAAAsE,qBAAoBS,EACxB,EAAG,K,gHCXP,IAAA9J,EAAAC,EAAA,UACA8E,EAAA9E,EAAA,iBAKC,WAEG,IAAI4O,EAAgB,GAChBC,EAAuB,GACvBC,GAA0B,EAC1BC,EAAYhO,SAASc,KAAKmN,YAE9BlM,OAAOvB,iBAAiB,SAAU,KAE9B,MAAMkG,EAAQ1G,SAASc,KAAKmN,YACtBC,EAAYxH,EAAQsH,EAAY,WAAa,aAE/CE,IAAcL,IACdE,GAA0B,GAGC,GAA3BA,GAAoCG,GAAaJ,IAChC,YAAbI,GAA2BxH,EAhBpB,OAkBP,EAAA1H,EAAA6E,kBAAiBE,EAAAuD,mBACjBwG,EAAuBI,EACvBH,GAA0B,GAGb,cAAbG,GAA6BxH,EAvBtB,MAyBkB,GAArB3C,EAAAuD,oBACA,EAAAtI,EAAA8E,sBAEJgK,EAAuBI,EACvBH,GAA0B,IAIlCF,EAAgBK,EAChBF,EAAYtH,GAEpB,CArCC,E","sources":["src/OrchardCore.Themes/TheAdmin/Assets/js/TheAdmin/TheAdmin.ts","src/OrchardCore.Themes/TheAdmin/Assets/js/TheAdmin/menu.ts","src/OrchardCore.Themes/TheAdmin/Assets/js/constants.ts",".scripts/bloom/helpers/globals.ts",".scripts/bloom/helpers/removeDiacritics.ts","node_modules/@parcel/transformer-js/src/esmodule-helpers.js","node_modules/js-cookie/dist/js.cookie.js","src/OrchardCore.Themes/TheAdmin/Assets/js/TheAdmin/userPreferencesPersistor.ts","src/OrchardCore.Themes/TheAdmin/Assets/js/TheAdmin/resizeDetector.ts"],"sourcesContent":["import { initializeMenu } from \"./menu\";\nimport \"./resizeDetector\";\n///<reference path=\"@types/bootstrap/index.d.ts\" />\n\ninitializeMenu();\n\nfunction confirmDialog({ callback, ...options }: { callback: (response: boolean) => void; [key: string]: any }) {\n    const defaultOptions = $(\"#confirmRemoveModalMetadata\").data();\n    const { title, message, okText, cancelText, okClass, cancelClass } = $.extend({}, defaultOptions, options);\n\n    $(\n        '<div id=\"confirmRemoveModal\" class=\"modal\" tabindex=\"-1\" role=\"dialog\">\\\n        <div class=\"modal-dialog modal-dialog-centered\" role=\"document\">\\\n            <div class=\"modal-content\">\\\n                <div class=\"modal-header\">\\\n                    <h5 class=\"modal-title\">' +\n            title +\n            '</h5>\\\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\\\n                </div>\\\n                <div class=\"modal-body\">\\\n                    <p>' +\n            message +\n            '</p>\\\n                </div>\\\n                <div class=\"modal-footer\">\\\n                    <button id=\"modalOkButton\" type=\"button\" class=\"btn ' +\n            okClass +\n            '\">' +\n            okText +\n            '</button>\\\n                    <button id=\"modalCancelButton\" type=\"button\" class=\"btn ' +\n            cancelClass +\n            '\" data-bs-dismiss=\"modal\">' +\n            cancelText +\n            \"</button>\\\n                </div>\\\n            </div>\\\n        </div>\\\n    </div>\",\n    ).appendTo(\"body\");\n\n    const modalElement = document.getElementById(\"confirmRemoveModal\");\n\n    if (modalElement) {\n        const confirmModal = new bootstrap.Modal(modalElement, {\n            backdrop: \"static\",\n            keyboard: false,\n        });\n\n        confirmModal.show();\n\n        document.getElementById(\"confirmRemoveModal\")?.addEventListener(\"hidden.bs.modal\", function () {\n            document.getElementById(\"confirmRemoveModal\")?.remove();\n            confirmModal.dispose();\n        });\n\n        $(\"#modalOkButton\").click(function () {\n            callback(true);\n            confirmModal.hide();\n        });\n\n        $(\"#modalCancelButton\").click(function () {\n            callback(false);\n            confirmModal.hide();\n        });\n    }\n}\n\n(function () {\n    // Prevents page flickering while downloading css\n    document.addEventListener(\"DOMContentLoaded\", () => {\n        document.body.classList.remove(\"preload\");\n    });\n})();\n\n$(function () {\n    $(\"body\").on(\"click\", '[data-url-af~=\"RemoveUrl\"], a[itemprop~=\"RemoveUrl\"]', function () {\n        const _this = $(this);\n        if (_this.filter('a[itemprop~=\"UnsafeUrl\"]').length == 1) {\n            console.warn(\"Please use data-url-af instead of itemprop attribute for confirm modals. Using itemprop will eventually become deprecated.\");\n        }\n        // don't show the confirm dialog if the link is also UnsafeUrl, as it will already be handled below.\n        if (_this.filter('[data-url-af~=\"UnsafeUrl\"], a[itemprop~=\"UnsafeUrl\"]').length == 1) {\n            return false;\n        }\n        confirmDialog({\n            ..._this.data(),\n            callback: function (resp: any) {\n                if (resp) {\n                    const url = _this.attr(\"href\");\n                    if (url == undefined) {\n                        let form = _this.parents(\"form\");\n                        // This line is reuired in case we used the FormValueRequiredAttribute\n                        form.append($('<input type=\"hidden\" name=\"' + _this.attr(\"name\") + '\" value=\"' + _this.attr(\"value\") + '\" />'));\n                        form.submit();\n                    } else {\n                        window.location.href = url;\n                    }\n                }\n            },\n        });\n\n        return false;\n    });\n});\n\n$(function () {\n    const magicToken = $(\"input[name=__RequestVerificationToken]\").first();\n    if (magicToken) {\n        $(\"body\").on(\"click\", 'a[data-url-af~=\"UnsafeUrl\"], a[itemprop~=\"UnsafeUrl\"]', function () {\n            const _this = $(this);\n            if (_this.filter('a[itemprop~=\"UnsafeUrl\"]').length == 1) {\n                console.warn(\"Please use data-url-af instead of itemprop attribute for confirm modals. Using itemprop will eventually become deprecated.\");\n            }\n            const hrefParts = _this.attr(\"href\")?.split(\"?\");\n\n            if (hrefParts == undefined) {\n                return false;\n            }\n\n            let form = $('<form action=\"' + hrefParts[0] + '\" method=\"POST\" />');\n            form.append(magicToken.clone());\n            if (hrefParts.length > 1) {\n                const queryParts = hrefParts[1].split(\"&\");\n                for (let i = 0; i < queryParts.length; i++) {\n                    const queryPartKVP = queryParts[i].split(\"=\");\n                    //trusting hrefs in the page here\n                    form.append($('<input type=\"hidden\" name=\"' + decodeURIComponent(queryPartKVP[0]) + '\" value=\"' + decodeURIComponent(queryPartKVP[1]) + '\" />'));\n                }\n            }\n\n            form.css({ position: \"absolute\", left: \"-9999em\" });\n            $(\"body\").append(form);\n\n            const unsafeUrlPrompt = _this.data(\"unsafe-url\");\n\n            if (unsafeUrlPrompt && unsafeUrlPrompt.length > 0) {\n                confirmDialog({\n                    ..._this.data(),\n                    callback: function (resp: any) {\n                        if (resp) {\n                            form.submit();\n                        }\n                    },\n                });\n\n                return false;\n            }\n\n            if (_this.filter('[data-url-af~=\"RemoveUrl\"], a[itemprop~=\"RemoveUrl\"]').length == 1) {\n                confirmDialog({\n                    ..._this.data(),\n                    callback: function (resp: any) {\n                        if (resp) {\n                            form.submit();\n                        }\n                    },\n                });\n\n                return false;\n            }\n\n            form.submit();\n            return false;\n        });\n    }\n});\n\n(function () {\n    // Tooltips\n    const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle=\"tooltip\"]'));\n    tooltipTriggerList.map(function (tooltipTriggerEl) {\n        return new bootstrap.Tooltip(tooltipTriggerEl);\n    });\n})();\n\n//Prevent multi submissions on forms\n$(\"body\").on(\"submit\", \"form.no-multisubmit\", function (e) {\n    const submittingClass = \"submitting\";\n    const form = $(this);\n\n    if (form.hasClass(submittingClass)) {\n        e.preventDefault();\n        return;\n    }\n\n    form.addClass(submittingClass);\n\n    // safety-nest in case the form didn't refresh the page\n    setTimeout(function () {\n        form.removeClass(submittingClass);\n    }, 5000);\n});\n\ndeclare global {\n    interface Window {\n        confirmDialog: typeof confirmDialog;\n    }\n}\n\nwindow.confirmDialog = confirmDialog;\n\nexport { confirmDialog };\n","import { isCompactExplicit, setCompactExplicit } from '../constants';\nimport { getTenantName, getAdminPrefix } from '@orchardcore/bloom/helpers/globals';\nimport { persistAdminPreferences } from './userPreferencesPersistor';\n\nlet leftNav: HTMLElement | null = null;\nlet menuInitialized = false;\n\nconst getSelectedNavHashStorageKey = () => `${getTenantName()}-selectedNavHash`;\n\nconst persistSelectedNavHash = (hash: string | null) => {\n    try {\n        if (hash === null) {\n            sessionStorage.removeItem(getSelectedNavHashStorageKey());\n        } else {\n            sessionStorage.setItem(getSelectedNavHashStorageKey(), hash);\n        }\n    } catch (error) {\n        console.error('Error storing selected navigation hash', error);\n    }\n};\n\nconst getSelectedNavHashFromDom = (nav: HTMLElement): string | null => {\n    const deepestLi = Array\n        .from(nav.querySelectorAll<HTMLLIElement>(\"li.active\"))\n        .at(-1);\n\n    return deepestLi\n        ?.querySelector<HTMLAnchorElement>(\"a[data-admin-hash]\")\n        ?.dataset.adminHash ?? null;\n};\n\nconst applySelectedNavLink = (nav: HTMLElement, selectedLink: HTMLAnchorElement) => {\n    nav.querySelectorAll('li.active').forEach(li => li.classList.remove('active'));\n    nav.querySelectorAll<HTMLElement>('ul.collapse.show').forEach(ul => ul.classList.remove('show'));\n    nav.querySelectorAll<HTMLElement>('.item-label[data-bs-toggle=\"collapse\"][aria-expanded=\"true\"]')\n        .forEach(label => label.setAttribute('aria-expanded', 'false'));\n\n    let currentItem = selectedLink.closest('li');\n\n    while (currentItem) {\n        currentItem.classList.add('active');\n\n        const childMenu = currentItem.querySelector<HTMLElement>(':scope > figure > ul.collapse');\n        if (childMenu) {\n            childMenu.classList.add('show');\n        }\n\n        const toggle = currentItem.querySelector<HTMLElement>(':scope > figure > figcaption > .item-label[data-bs-toggle=\"collapse\"]');\n        if (toggle) {\n            toggle.setAttribute('aria-expanded', 'true');\n        }\n\n        currentItem = currentItem.parentElement?.closest('li') ?? null;\n    }\n};\n\nconst applySelectedNavFromSessionStorage = () => {\n    // Don't apply stored selection if we're at the admin root path.\n    // This handles both single-tenant (/admin) and multi-tenant (/tenant-prefix/admin) scenarios.\n    const adminPrefix = getAdminPrefix().toLowerCase();\n    const currentPath = window.location.pathname.toLowerCase();\n\n    if (currentPath === adminPrefix || currentPath === adminPrefix + '/') {\n        persistSelectedNavHash(null);\n        return true;\n    }\n\n    let selectedNavHash: string | null;\n\n    try {\n        selectedNavHash = sessionStorage.getItem(getSelectedNavHashStorageKey());\n    } catch (error) {\n        console.error('Error reading selected navigation hash', error);\n        return true;\n    }\n\n    // No persisted selection yet: keep the server-selected menu state.\n    if (!selectedNavHash) {\n        return true;\n    }\n\n    const nav = document.getElementById('left-nav');\n\n    if (!nav) {\n        return document.readyState === 'complete';\n    }\n\n    const navLinks = nav.querySelectorAll<HTMLAnchorElement>('a[data-admin-hash]');\n\n    if (navLinks.length === 0) {\n        return document.readyState === 'complete';\n    }\n\n    const hasServerSelection = nav.querySelector('li.active a[data-admin-hash]') !== null;\n\n    // Wait until the server-side active state is present (or loading has finished)\n    // so we normalize once instead of repeatedly re-applying during incremental render.\n    if (!hasServerSelection && document.readyState !== 'complete') {\n        return false;\n    }\n\n    const selectedLink = Array.from(navLinks)\n        .find(link => link.dataset.adminHash === selectedNavHash);\n\n    if (!selectedLink) {\n        return document.readyState === 'complete';\n    }\n\n    applySelectedNavLink(nav, selectedLink);\n\n    return true;\n};\n\nconst initializeMenu = () => {\n    if (menuInitialized) {\n        return;\n    }\n\n    menuInitialized = true;\n\n    // When we load compact status from preferences we need to do some other tasks besides adding the class to the body.\n    // UserPreferencesLoader has already added the needed class.\n    $(function () {\n        // We set leftbar to compact if :\n        // 1. That preference was stored by the user the last time he was on the page\n        // 2. Or it's the first time on page and page is small.\n        if ($('body').hasClass('left-sidebar-compact')\n            || (($('body').hasClass('no-admin-preferences') && $(window).width() < 768))) {\n            setCompactStatus(false);\n        }\n    });\n\n    $('span.title').each(function () {\n        $(this).prev('.icon').prop('title', $(this).text());\n    });\n\n    $('.leftbar-compactor').on('click', function () {\n        $('body').hasClass('left-sidebar-compact') ? unSetCompactStatus() : setCompactStatus(true);\n    });\n\n    $('#left-nav li.has-items').on('click', function () {\n        $('#left-nav li.has-items').removeClass(\"visible\");\n        $(this).addClass(\"visible\");\n    });\n\n    $('#left-nav').on('click', 'a[data-admin-hash][href^=\"/\"]', function () {\n        persistSelectedNavHash(String($(this).data('admin-hash')));\n    });\n\n    $(document).on(\"click\", function (event) {\n        var $trigger = $(\"#left-nav li.has-items\");\n        if ($trigger !== event.target && !$trigger.has(event.target).length) {\n            $('#left-nav li.has-items').removeClass(\"visible\");\n        }\n    });\n\n    leftNav = document.getElementById(\"left-nav\");\n\n    // create an Observer instance\n    const resizeObserver = new ResizeObserver(() => {\n        if (isCompactExplicit) {\n            if (leftNav && (leftNav.scrollHeight > leftNav.clientHeight)) {\n                document.body.classList.add(\"scroll\");\n            }\n            else {\n                document.body.classList.remove(\"scroll\");\n            }\n        }\n        else {\n            document.body.classList.remove(\"scroll\");\n        }\n    });\n\n    // start observing a DOM node\n    if (leftNav != null) {\n        resizeObserver.observe(leftNav);\n\n        // If no selected nav hash is stored, try to get it from the DOM and persist it.\n        let selectedNavHash: string | null = null;\n\n        try {\n            selectedNavHash = sessionStorage.getItem(getSelectedNavHashStorageKey());\n        } catch (error) {\n            console.error('Error reading selected navigation hash', error);\n        }\n\n        if (!selectedNavHash) {\n            selectedNavHash = getSelectedNavHashFromDom(leftNav);\n\n            if (selectedNavHash) {\n                persistSelectedNavHash(selectedNavHash);\n            }\n        }\n    }\n};\n\nconst setCompactStatus = (explicit) => {\n    // This if is to avoid that when sliding from expanded to compact the\n    // underliyng ul is visible while shrinking. It is ugly.\n    if (!$('body').hasClass('left-sidebar-compact')) {\n        var labels = $('#left-nav ul.menu-admin > li > figure > figcaption > .item-label');\n        labels.css('background-color', 'transparent');\n        setTimeout(function () {\n            labels.css('background-color', '');\n        }, 200);\n    }\n\n    // Transfer scroll position from expanded scroller (.menu-admin) to compact scroller (#left-nav)\n    const menuAdmin = document.querySelector<HTMLElement>('#left-nav ul.menu-admin');\n    const savedScroll = menuAdmin ? menuAdmin.scrollTop : 0;\n\n    $('body').addClass('left-sidebar-compact');\n\n    if (leftNav) {\n        leftNav.scrollTop = savedScroll;\n    }\n\n    // When leftbar is expanded  all ul tags are collapsed.\n    // When leftbar is compacted we don't want the first level collapsed.\n    // We want it expanded so that hovering over the root buttons shows the full submenu\n    $('#left-nav ul.menu-admin > li > figure > ul').removeClass('collapse');\n    // When hovering, don't want toggling when clicking on label\n    $('#left-nav ul.menu-admin > li > figure > figcaption > .item-label').attr('data-bs-toggle', '');\n    $('#left-nav li.has-items').removeClass(\"visible\");\n\n    //after menu has collapsed we set the transitions to none so that we don't do any transition\n    //animation when open a sub-menu\n    setTimeout(function () {\n        $('#left-nav > ul > li').css(\"transition\", \"none\");\n    }, 200);\n\n    if (explicit == true) {\n        setCompactExplicit(true);\n    }\n\n    persistAdminPreferences();\n};\n\nconst unSetCompactStatus = () => {\n    // Transfer scroll position from compact scroller (#left-nav) to expanded scroller (.menu-admin)\n    const savedScroll = leftNav ? leftNav.scrollTop : 0;\n\n    $('body').removeClass('left-sidebar-compact');\n\n    // resetting what we disabled for compact state\n    $('#left-nav ul.menu-admin > li > figure > ul').addClass('collapse');\n    $('#left-nav ul.menu-admin > li > figure > figcaption > button.item-label').attr('data-bs-toggle', 'collapse');\n    $('#left-nav li.has-items').removeClass(\"visible\");\n    $('#left-nav > ul > li').css(\"transition\", \"\");\n\n    const menuAdmin = document.querySelector<HTMLElement>('#left-nav ul.menu-admin');\n    if (menuAdmin) {\n        menuAdmin.scrollTop = savedScroll;\n    }\n\n    setCompactExplicit(false);\n    persistAdminPreferences();\n};\n\nexport {\n    applySelectedNavFromSessionStorage,\n    initializeMenu,\n    setCompactStatus,\n    unSetCompactStatus,\n};\n","import { getTenantName } from '@orchardcore/bloom/helpers/globals';\nimport Cookies from 'js-cookie';\n\nlet isCompactExplicit = false;\n\nconst setCompactExplicit = (value: boolean) => {\n    isCompactExplicit = value;\n}\n\nconst getAdminPreferenceKey = () => getTenantName() + '-adminPreferences';\n\nconst getAdminPreferences = () => {\n    const storedValue = localStorage.getItem(getAdminPreferenceKey());\n\n    if (!storedValue) {\n        return {};\n    }\n\n    try {\n        return JSON.parse(storedValue);\n    } catch (ex) {\n        console.error('Error retrieving admin preferences', ex);\n        return {};\n    }\n};\n\nconst setAdminPreferences = (adminPreferences) => {\n    if (adminPreferences == null) {\n        console.error('Error setting admin preferences, argument is null');\n        return;\n    }\n\n    const key = getAdminPreferenceKey();\n\n    try {\n        localStorage.setItem(key, JSON.stringify(adminPreferences));\n        Cookies.set(key, JSON.stringify(adminPreferences), { expires: 360 });\n    } catch (ex) {\n        console.error('Error setting admin preferences', ex);\n    }\n};\n\nexport {\n    isCompactExplicit,\n    setCompactExplicit,\n    getAdminPreferences,\n    setAdminPreferences\n}\n\n","import removeDiacritics from \"./removeDiacritics\";\n\nconst getTenantName = () => document.documentElement.getAttribute(\"data-tenant\") || \"default\";\n\nconst getAdminPrefix = () => document.documentElement.getAttribute(\"data-admin-prefix\") || \"/admin\";\n\nconst getTechnicalName = (name: string) => {\n    let result = \"\",\n        c;\n\n    if (!name || name.length == 0) {\n        return \"\";\n    }\n\n    name = removeDiacritics(name);\n\n    for (let i = 0; i < name.length; i++) {\n        c = name[i];\n        if (isLetter(c) || (isNumber(c) && i > 0)) {\n            result += c;\n        }\n    }\n\n    return result;\n};\n\nconst isLetter = (str: string) => {\n    return str.length === 1 && str.match(/[a-z]/i);\n};\n\nconst isNumber = (str: string) => {\n    return str.length === 1 && str.match(/[0-9]/i);\n};\n\nconst getAntiForgeryToken = (): string | null => {\n    const input = document.querySelector<HTMLInputElement>(\n        'input[name=\"__RequestVerificationToken\"]'\n    );\n    return input?.value ?? null;\n};\n\n/**\n * Returns the tenant path base (e.g. \"/authserver\", \"/tenant\") from the current page.\n * Reads from a `<script type=\"application/json\">` element whose id ends with `-data`\n * and contains a `pathBase` property, or falls back to an empty string (root tenant).\n */\nconst getTenantPathBase = (dataElementId?: string): string => {\n    if (dataElementId) {\n        const el = document.getElementById(dataElementId);\n        if (el) {\n            try { return JSON.parse(el.textContent || \"{}\").pathBase || \"\"; }\n            catch { return \"\"; }\n        }\n    }\n\n    // Fallback: scan for any script[type=\"application/json\"][id$=\"-data\"] with a pathBase.\n    const scripts = document.querySelectorAll<HTMLScriptElement>('script[type=\"application/json\"][id$=\"-data\"]');\n    for (const script of Array.from(scripts)) {\n        try {\n            const data = JSON.parse(script.textContent || \"{}\");\n            if (typeof data.pathBase === \"string\") {\n                return data.pathBase;\n            }\n        }\n        catch { /* skip malformed JSON */ }\n    }\n\n    return \"\";\n};\n\nexport {\n    getAdminPrefix,\n    getAntiForgeryToken, \n    getTechnicalName, \n    getTenantName, \n    getTenantPathBase, \n    isLetter, \n    isNumber \n};\n","﻿/*\n   Licensed under the Apache License, Version 2.0 (the \"License\");\n   you may not use this file except in compliance with the License.\n   You may obtain a copy of the License at\n\n       http://www.apache.org/licenses/LICENSE-2.0\n\n   Unless required by applicable law or agreed to in writing, software\n   distributed under the License is distributed on an \"AS IS\" BASIS,\n   WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n   See the License for the specific language governing permissions and\n   limitations under the License.\n*/\nvar defaultDiacriticsRemovalMap = [\n  {\n    base: \"A\",\n    letters:\n      \"\\u0041\\u24B6\\uFF21\\u00C0\\u00C1\\u00C2\\u1EA6\\u1EA4\\u1EAA\\u1EA8\\u00C3\\u0100\\u0102\\u1EB0\\u1EAE\\u1EB4\\u1EB2\\u0226\\u01E0\\u00C4\\u01DE\\u1EA2\\u00C5\\u01FA\\u01CD\\u0200\\u0202\\u1EA0\\u1EAC\\u1EB6\\u1E00\\u0104\\u023A\\u2C6F\",\n  },\n  { base: \"AA\", letters: \"\\uA732\" },\n  { base: \"AE\", letters: \"\\u00C6\\u01FC\\u01E2\" },\n  { base: \"AO\", letters: \"\\uA734\" },\n  { base: \"AU\", letters: \"\\uA736\" },\n  { base: \"AV\", letters: \"\\uA738\\uA73A\" },\n  { base: \"AY\", letters: \"\\uA73C\" },\n  { base: \"B\", letters: \"\\u0042\\u24B7\\uFF22\\u1E02\\u1E04\\u1E06\\u0243\\u0182\\u0181\" },\n  { base: \"C\", letters: \"\\u0043\\u24B8\\uFF23\\u0106\\u0108\\u010A\\u010C\\u00C7\\u1E08\\u0187\\u023B\\uA73E\" },\n  { base: \"D\", letters: \"\\u0044\\u24B9\\uFF24\\u1E0A\\u010E\\u1E0C\\u1E10\\u1E12\\u1E0E\\u0110\\u018B\\u018A\\u0189\\uA779\" },\n  { base: \"DZ\", letters: \"\\u01F1\\u01C4\" },\n  { base: \"Dz\", letters: \"\\u01F2\\u01C5\" },\n  {\n    base: \"E\",\n    letters:\n      